  // ----- local editable state (so typing always works) -----
  const [localBusiness, setLocalBusiness] = useState(businessName)
  const [localDisplay, setLocalDisplay] = useState(displayName)
  const [localLocation, setLocalLocation] = useState(locationText)
  const [localEmail, setLocalEmail] = useState(email)

  useEffect(() => setLocalBusiness(businessName), [businessName])
  useEffect(() => setLocalDisplay(displayName), [displayName])
  useEffect(() => setLocalLocation(locationText), [locationText])
  useEffect(() => setLocalEmail(email), [email])

  // ----- events (START EMPTY) -----
  const [localPrevVends, setLocalPrevVends] = useState<string[]>([])
  const [newVend, setNewVend] = useState("")
  const addInputRef = useRef<HTMLInputElement | null>(null)

  useEffect(() => {
    if (previousVends === undefined) return
    setLocalPrevVends(previousVends.slice(0, 4))
  }, [previousVends])

  const pushPrevVends = (next: string[]) => {
    const trimmed = next.map((s) => s.trim()).filter(Boolean).slice(0, 4)
    setLocalPrevVends(trimmed)
    onChangePreviousVends?.(trimmed)
  }

  const addVend = (raw: string) => {
    const text = (raw || "").trim()
    if (!text) return
    if (localPrevVends.length >= 4) return
    pushPrevVends([...localPrevVends, text])
    setNewVend("")
    addInputRef.current?.focus()
  }

  const deleteVendAt = (idx: number) => {
    const next = localPrevVends.filter((_, i) => i !== idx)
    pushPrevVends(next)
  }

  const parsedPrevVends = useMemo(() => localPrevVends.map(parseEventLine), [localPrevVends])

  // ----- colors -----
  const [localBanner, setLocalBanner] = useState(bannerColor)
  const [localBg, setLocalBg] = useState(backgroundColor)
  useEffect(() => setLocalBanner(bannerColor), [bannerColor])
  useEffect(() => setLocalBg(backgroundColor), [backgroundColor])

  // ----- profile image upload -----
  const fileInputRef = useRef<HTMLInputElement | null>(null)
  const [localImgUrl, setLocalImgUrl] = useState(profileImageUrl || "")
  const objectUrls = useRef<string[]>([])

  useEffect(() => setLocalImgUrl(profileImageUrl || ""), [profileImageUrl])

  useEffect(() => {
    return () => {
      objectUrls.current.forEach((u) => URL.revokeObjectURL(u))
      objectUrls.current = []
    }
  }, [])

  const openPicker = () => fileInputRef.current?.click()

  const handleFile = (file: File) => {
    if (!file.type.startsWith("image/")) return
    const url = URL.createObjectURL(file)
    objectUrls.current.push(url)
    setLocalImgUrl(url)
    onChangeProfileImage?.(file, url)
  }

  const onFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    handleFile(file)
    e.target.value = ""
  }

  const onDrop = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    const file = e.dataTransfer.files?.[0]
    if (!file) return
    handleFile(file)
  }

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
  }

  const locationSize = Math.max(localLocation.length || 0, 8)

  const hasAnyEvents = localPrevVends.length > 0
  const vendPlaceholder = hasAnyEvents ? "Type an event..." : "Vended Event 2026"

  /* ---------------- Links dropdown state ---------------- */
  const [linksOpen, setLinksOpen] = useState(false)
  const [activeLinkKeys, setActiveLinkKeys] = useState<LinkKey[]>([])
  const [activeInputKey, setActiveInputKey] = useState<LinkKey | null>(null)

  const [linksByKey, setLinksByKey] = useState<Record<LinkKey, string>>({
    website: "",
    shop: "",
    instagram: "",
    x: "",
    facebook: "",
    tumblr: "",
    pixiv: "",
    bluesky: "",
  })

  const linksWrapRef = useRef<HTMLDivElement | null>(null)

  const linkOptions: LinkOption[] = useMemo(
    () => [
      { key: "website", label: "Main Website", rightText: "Recommended", icon: <HomeIcon className="text-[#262626]" /> },
      { key: "shop", label: "Main Shop", rightText: "Recommended", icon: <ShopIcon className="text-[#262626]" /> },
      { key: "instagram", label: "Instagram", rightText: "Recommended", icon: <InstagramIcon className="text-[#262626]" /> },
      { key: "x", label: "X / Twitter", icon: <XIcon className="text-[#262626]" /> },
      { key: "facebook", label: "Facebook", icon: <FacebookIcon className="text-[#262626]" /> },
      { key: "tumblr", label: "Tumblr", icon: <TumblrIcon className="text-[#262626]" /> },
      { key: "pixiv", label: "Pixiv", icon: <PixivIcon className="text-[#262626]" /> },
      { key: "bluesky", label: "Bluesky", icon: <BlueskyIcon className="text-[#262626]" /> },
    ],
    []
  )

  function addKey(key: LinkKey) {
    setActiveLinkKeys((prev) => {
      if (prev.includes(key)) return prev
      return [...prev, key]
    })
    setLinksOpen(false)
    setActiveInputKey(key)
  }

  function removeKey(key: LinkKey) {
    setActiveLinkKeys((prev) => prev.filter((k) => k !== key))
    setLinksByKey((prev) => ({ ...prev, [key]: "" }))
    setLinksOpen(false)
    setActiveInputKey((cur) => (cur === key ? null : cur))
  }

  useEffect(() => {
    function onDocDown(e: MouseEvent) {
      if (!linksWrapRef.current) return
      if (!linksWrapRef.current.contains(e.target as Node)) {
        setLinksOpen(false)
        setActiveInputKey(null)
      }
    }
    function onEsc(e: KeyboardEvent) {
      if (e.key === "Escape") {
        setLinksOpen(false)
        setActiveInputKey(null)
      }
    }
    document.addEventListener("mousedown", onDocDown)
    document.addEventListener("keydown", onEsc)
    return () => {
      document.removeEventListener("mousedown", onDocDown)
      document.removeEventListener("keydown", onEsc)
    }
  }, [])
  /* ----------------------------------------------------- */

  /* ---------------- Merch dropdown state ---------------- */
  const maxMerchTags = 8
  const [merchOpen, setMerchOpen] = useState(false)
  const [merchQuery, setMerchQuery] = useState("")
  const [merchSelected, setMerchSelected] = useState<string[]>([])
  const merchWrapRef = useRef<HTMLDivElement | null>(null)
  const merchInputRef = useRef<HTMLInputElement | null>(null)

  const merchLimitReached = merchSelected.length >= maxMerchTags
  const merchSelectedSet = useMemo(() => new Set(merchSelected.map(keyify)), [merchSelected])

  const merchVisibleRows = useMemo(() => {
    const q = keyify(merchQuery)
    const out: Row[] = []
    let currentHeader: GroupKey | null = null
    let headerAdded = false

    for (const row of ROWS) {
      if (row.type === "header") {
        currentHeader = row.label
        headerAdded = false
        continue
      }

      if (merchSelectedSet.has(keyify(row.label))) continue
      if (q && !keyify(row.label).includes(q)) continue

      if (!headerAdded && currentHeader) {
        out.push({ type: "header", label: currentHeader })
        headerAdded = true
      }

      out.push(row)
    }

    return out
  }, [merchQuery, merchSelectedSet])

  function addMerchTag(raw: string) {
    const label = normalize(raw)
    if (!label) return
    const k = keyify(label)
    if (merchSelectedSet.has(k)) return
    if (merchLimitReached) return
    setMerchSelected((prev) => [...prev, label])
  }

  function removeMerchTag(label: string) {
    const k = keyify(label)
    setMerchSelected((prev) => prev.filter((t) => keyify(t) !== k))
  }

  function pickMerchOption(label: string) {
    addMerchTag(label)
    setMerchQuery("")
    setMerchOpen(false)
  }

  function onMerchEnter(e: React.KeyboardEvent<HTMLInputElement>) {
    if (e.key !== "Enter") return
    e.preventDefault()
    if (merchLimitReached) return

    const q = normalize(merchQuery)
    if (!q) return

    const exact = ROWS.find((r) => r.type === "item" && keyify(r.label) === keyify(q)) as
      | Extract<Row, { type: "item" }>
      | undefined

    if (exact) {
      pickMerchOption(exact.label)
      return
    }

    addMerchTag(q)
    setMerchQuery("")
    setMerchOpen(false)
  }

  useEffect(() => {
    function onDocDown(e: MouseEvent) {
      if (!merchWrapRef.current) return
      if (!merchWrapRef.current.contains(e.target as Node)) setMerchOpen(false)
    }
    function onEsc(e: KeyboardEvent) {
      if (e.key === "Escape") setMerchOpen(false)
    }
    document.addEventListener("mousedown", onDocDown)
    document.addEventListener("keydown", onEsc)
    return () => {
      document.removeEventListener("mousedown", onDocDown)
      document.removeEventListener("keydown", onEsc)
    }
  }, [])
  /* ----------------------------------------------------- */

